import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"子夏易傳 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"子夏易傳 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"classics/zixia/011.md","filePath":"classics/zixia/011.md"}'),i={name:"classics/zixia/011.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>卦辭：小畜，亨，密雲不雨，自我西郊。</p><p>彖曰：小畜，柔得位，而上下應之，曰小畜。健而巽，剛中而志行，乃亨。密雲不雨，尚往也。自我西郊，施未行也。</p><p>子夏：小畜，隂上得位，而陽皆應之也，柔畜，剛也。大為小所畜，其畜不能全。小畜而已也，故健而巽，剛下柔也。剛居中，巽柔而從其畜。志得而後通也。雨者，隂陽和，隂行其道，則盛而為雨。小畜，志於上，往也，自得其位而已。使陽而巽，其澤不足，以下濟也。則密雲而不雨也。雲自西郊而東也，隂消而退未能行施也。小人來，居上位，非中正之德，君子無所承也。其何足光哉，不能畜君子之大也。</p><p>象曰：風行天上，小畜。君子以懿文德。</p><p>子夏：風行天上，而不能畜大也。言行德之大也。文德者，德之小也。君子之道，無所備也。畜其文德，與時行也。</p><p>初九，復自道，何其咎，吉。</p><p>象曰：復自道，其義吉也。</p><p>子夏：乾，本上也。三陽尚上也，應而歸焉。巽以行志，復自我道，何以咎哉，其義吉也。</p><p>九二，牽復，吉。</p><p>象曰：牽復在中，亦不自失也。</p><p>子夏：志乎畜而不能全也。雖與我而非應，可以牽，而巽之自復其道。得時之中，故吉也。</p><p>九三，輿説輻，夫妻反目。</p><p>象曰：夫妻反目，不能正室也。</p><p>子夏：隂之微，不能大畜，其亦已矣。故初應二，牽巽志而行，自復其道，至於三，斯極之矣。上飛制下，終於小畜，理固然也。思不能行，行脫其輻也。陽不制隂，夫不正室也。</p><p>六四，有孚，血去，惕出，無咎。</p><p>象曰：有孚，惕出，上合志也。</p><p>子夏：一隂也，而眾陽趨焉，非其所治者也。則懼其傷害矣，奉與五剛，誠信相與，近而相親，固也。尊而肅民，安也。何傷害，惕懼之，患哉。可無咎乎。</p><p>九五，有孚，攣如。富以其鄰。</p><p>象曰：有孚，攣如。不獨富也。</p><p>子夏：卦唯一隂，鄰而奉已，已亦交愛，有孚攣如，資貨與同，不獨自厚，巽而行志者也。</p><p>上九，既雨，既處，尚德載婦，貞厲。月幾望，君子徵兇。</p><p>象曰：既雨，既處德，積載也。君子徵兇，有所疑也。</p><p>子夏：小畜，畜其餘未始於道，小不能畜，陽得行其志，上不可全無。下無所遂志，故其終焉。既雨，得行其道也，旣處安其所也。尚德載陽為所畜也，隂專於陽危之道也。月近望，隂盈盛也。君子徵兇，陽疑而不敢進也。以爻語之，則得志以體。言之，則小畜。此言巽，隂之終而不係於爻也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
